def crear_etapa_y_migrar_categorias(apps, schema_editor):
    Etapa = apps.get_model(
        'nucleo',
        'Etapa'
    )

    CategoriaMision = apps.get_model(
        'nucleo',
        'CategoriaMision'
    )

    Mision = apps.get_model(
        'nucleo',
        'Mision'
    )

    # ----------------------------------------------
    # CREAR ETAPA 1
    # ----------------------------------------------

    etapa_1, _ = Etapa.objects.get_or_create(
        numero=1,
        defaults={
            'nombre': 'Etapa 1',
            'descripcion': '',
            'estado': 'activa',
            'fecha_inicio': timezone.now(),
        }
    )

    # ----------------------------------------------
    # CATEGORÍAS ORIGINALES
    # ----------------------------------------------

    categorias = [
        (
            'creador_personaje',
            'Creador de personaje',
            1,
        ),
        (
            'creacion_lore',
            'Creación de lore',
            2,
        ),
        (
            'juegos_casino',
            'Juegos de casino',
            3,
        ),
        (
            'mecanicas_jugador',
            'Mecánicas del jugador',
            4,
        ),
        (
            'npc',
            'NPC',
            5,
        ),
        (
            'creacion_mapa',
            'Creación del mapa',
            6,
        ),
        (
            'rogue_lite',
            'Rogue Lite',
            7,
        ),
    ]

    categorias_creadas = {}

    for slug, nombre, orden in categorias:
        categoria, _ = (
            CategoriaMision.objects.get_or_create(
                etapa=etapa_1,
                slug=slug,
                defaults={
                    'nombre': nombre,
                    'descripcion': '',
                    'activa': True,
                    'orden': orden,
                }
            )
        )

        categorias_creadas[slug] = categoria

    # ----------------------------------------------
    # ASOCIAR QUESTS ANTIGUAS
    # ----------------------------------------------

    for mision in Mision.objects.all():
        slug_antiguo = (
            mision.categoria_antigua
        )

        categoria = (
            categorias_creadas.get(
                slug_antiguo
            )
        )

        if categoria:
            mision.categoria_nueva = (
                categoria
            )

            mision.save(
                update_fields=[
                    'categoria_nueva'
                ]
            )


